param([string]$ScriptPath='', [Parameter(Mandatory=$true)][string]$ReportPath)
$ErrorActionPreference='Stop';if($ScriptPath -eq ''){$ScriptPath=Join-Path $PSScriptRoot 'native-furniture-control.ps1'};if(Test-Path -LiteralPath $ReportPath){throw 'Preserve earlier report'}
$tokens=$null;$errors=$null;$ast=[System.Management.Automation.Language.Parser]::ParseFile($ScriptPath,[ref]$tokens,[ref]$errors);if($errors.Count){throw ($errors|Out-String)}
foreach($name in @('Test-Integer','Get-ExactSlide','Get-ExactShape','Invoke-FurnitureCom','Stop-FurnitureLifecycle','Read-FurnitureFiniteNumber','New-FurniturePointProbe','Read-FurnitureSlicePoint','Get-FurnitureNativeCircleCenter','Get-FurnitureCurvedSliceBounds','Read-FurnitureChartPoint','Apply-FurnitureAction')){$fn=$ast.Find({param($n)$n -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq $name},$true);if($null -eq $fn){throw "Missing reviewed function$name"};Invoke-Expression $fn.Extent.Text}
$areaFn=$ast.Find({param($n)$n -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq 'Read-FurnitureAreaValue'},$true);if($null -ne $areaFn){Invoke-Expression $areaFn.Extent.Text}
$harness=[System.Management.Automation.Language.Parser]::ParseFile((Join-Path $PSScriptRoot 'native-furniture-harness-check.ps1'),[ref]$tokens,[ref]$errors);$factory=$harness.Find({param($n)$n -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq 'New-ChartPointFixture'},$true);if($null -eq $factory){throw 'Missing native-only mock factory'};Invoke-Expression $factory.Extent.Text
$script:events=New-Object 'System.Collections.Generic.List[string]';function Write-FurnitureStage([string]$Name,[string]$Status,[string]$ErrorMessage=$null){$script:events.Add($Name+':'+$Status)}
function Set-PointValues($Native,$Values,[int]$Count){$Native.points.Count=$Count;$array=New-Object 'object[]' $Count;for($i=0;$i -lt $Count;$i++){$array[$i]=$Native.point};$Native.points.Values=$array;$Native.series.Values[0]|Add-Member -MemberType NoteProperty -Name Values -Value $Values -Force}
function Action{param([int]$Index=1);return [pscustomobject]@{op='measure-chart-point';slideIndex=1;shapeName='Native ring';chartName='Native chart';seriesIndex=1;pointIndex=$Index;chartKind='marker';edge='center';valueSign=-1}}
function NativeArea([int]$Type=1){$n=New-ChartPointFixture 'marker';$n.chart.ChartType=$Type;$n.series.Values[0].ChartType=$Type;$n.point.Width=0;return $n}
$cases=New-Object 'System.Collections.Generic.List[object]'
$raw=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'fixtures/sh25-native-area-observations.json') -Raw|ConvertFrom-Json
foreach($witness in $raw.rows){$n=NativeArea ([int]$witness.raw.seriesChartType);$b=$witness.raw.nativeLocalBoundsPoints;$n.point.Left=$b[0];$n.point.Top=$b[1];$n.point.Width=$b[2];$n.point.Height=$b[3];$n.chartShape.Left=$witness.chart.left;$n.chartShape.Top=$witness.chart.top;foreach($name in @('Left','Top','Width','Height')){$n.overlay.$name=$witness.overlay.($name.ToLowerInvariant())};$values=@($witness.nativeSavedSeriesCache|Sort-Object index|ForEach-Object {[double]$_.value});Set-PointValues $n $values $values.Count;$action=Action $witness.raw.pointIndex;$action.edge=$witness.raw.edge;$probe=New-FurniturePointProbe $action 'actual-area';$result=Read-FurnitureChartPoint $n.presentation $action 'actual-area' $probe;if(-not $result.withinFourPixels){throw ('Actual native area tip still uses midpoint: '+$result.distancePixels)};$cases.Add([ordered]@{name=('actual-'+$witness.family+'-'+$witness.language+'-'+$witness.raw.seriesIndex+'-'+$witness.raw.pointIndex+'-'+$witness.raw.edge);distancePixels=$result.distancePixels;passed=$true})}
foreach($type in @(1,76,77)){foreach($value in @(20.0,-20.0,0.0)){$n=NativeArea $type;$n.point.Left=10;$n.point.Top=30;$n.point.Height=if($value -eq 0){0}else{40};$tip=if($value -lt 0){70}else{30};$n.overlay.Left=105;$n.overlay.Top=200+$tip-5;$n.overlay.Width=10;$n.overlay.Height=10;$lower=if($value -lt 0){1}else{0};$array=[Array]::CreateInstance([double],[int[]]@(2),[int[]]@($lower));$array.SetValue(7.0,$lower);$array.SetValue($value,$lower+1);Set-PointValues $n $array 2;$a=Action 2;$a.valueSign=if($value -lt 0){1}else{-1};$r=Read-FurnitureChartPoint $n.presentation $a 'signed-area';if(-not $r.withinFourPixels -or $script:forbiddenChartData){throw 'Native area sign/lower-bound selection failed'};$cases.Add([ordered]@{name=('type-'+$type+'-value-'+$value);passed=$true})}}
foreach($form in @('scalar','singleton-array','zero-singleton-array')){$n=NativeArea;$value=if($form -eq 'zero-singleton-array'){0.0}else{-5.0};$values=if($form -eq 'scalar'){$value}else{,[double[]]@($value)};Set-PointValues $n $values 1;$n.point.Left=10;$n.point.Top=30;$n.point.Height=if($value -eq 0){0}else{40};$n.overlay.Left=105;$n.overlay.Top=if($value -lt 0){265}else{225};$n.overlay.Width=10;$n.overlay.Height=10;$a=Action;$probe=New-FurniturePointProbe $a 'singleton-area';$r=Read-FurnitureChartPoint $n.presentation $a 'singleton-area' $probe;if(-not $r.withinFourPixels){throw 'Native scalar/singleton/zero area failed'};if($form -ne 'scalar' -and $probe.areaValueObservation.rank -ne 1){throw 'Native singleton-array identity was flattened'};$cases.Add([ordered]@{name=$form;passed=$true})}
foreach($type in @(4,65,63,66,-4169)){$n=New-ChartPointFixture 'marker';$n.chart.ChartType=$type;$n.series.Values[0].ChartType=$type;$n.series.Values[0]|Add-Member -MemberType ScriptProperty -Name Values -Value {throw 'Non-area must not read Values'};$n.overlay.Left=125;$n.overlay.Top=230;$a=Action;$r=Read-FurnitureChartPoint $n.presentation $a 'unchanged-marker';if(-not $r.withinFourPixels){throw 'Line/scatter route changed'};$cases.Add([ordered]@{name=('unchanged-native-type-'+$type);passed=$true})}
foreach($failure in @('getter','null','range-string','nan','infinite','boolean','rank2','wrong-count','scalar-count2','unknown','wide-bounds')){$n=NativeArea;$a=Action;$a.pointIndex=1;Set-PointValues $n @([double]20,[double]30) 2;switch($failure){'getter'{$n.series.Values[0]|Add-Member -Force -MemberType ScriptProperty -Name Values -Value {throw 'Injected actual Values getter failure'}};'null'{$n.series.Values[0].Values=$null};'range-string'{$n.series.Values[0].Values='=Sheet1!B2:B3'};'nan'{$n.series.Values[0].Values=@([double]::NaN,30)};'infinite'{$n.series.Values[0].Values=@([double]::PositiveInfinity,30)};'boolean'{$n.series.Values[0].Values=@($true,30)};'rank2'{$n.series.Values[0].Values=(New-Object 'double[,]' 1,2)};'wrong-count'{$n.series.Values[0].Values=@(20)};'scalar-count2'{$n.series.Values[0].Values=20};'unknown'{$n.series.Values[0].Values=@([pscustomobject]@{value=20},30)};'wide-bounds'{$n.point.Width=4}};$script:report=[ordered]@{actionPlan=[ordered]@{chartPoints=@();currentChartPointProbe=$null}};$message=$null;try{Apply-FurnitureAction $n.presentation $a 1}catch{$message=$_.Exception.Message};if($null -eq $message -or -not $script:officeOperationsStopped){throw ('Area refusal failed: '+$failure)};$snapshot=$report|ConvertTo-Json -Depth 20; $roundtrip=$snapshot|ConvertFrom-Json;if($failure -ne 'getter' -and $null -eq $roundtrip.actionPlan.currentChartPointProbe.areaValueObservation){throw 'Failed actual-value receipt was lost'};$eventCount=$script:events.Count;try{Apply-FurnitureAction $n.presentation $a 2}catch{};if($eventCount -ne $script:events.Count){throw 'Area refusal allowed further native calls'};$cases.Add([ordered]@{name=('refuse-'+$failure);error=$message;serializedFailure=$roundtrip;passed=$true})}
[ordered]@{passed=$true;officeConstructed=$false;valuesWritten=$false;chartDataRead=$script:forbiddenChartData;cases=@($cases.ToArray())}|ConvertTo-Json -Depth 24|Set-Content -LiteralPath $ReportPath -Encoding UTF8
Write-Output ('Independent native area tip: '+$cases.Count+' actual/signed/unchanged/refusal controls, no Office')
